WITH remaining_keys AS (SELECT channel, promo_code FROM promotions EXCEPT DISTINCT SELECT channel, promo_code FROM promotions WHERE discount_pct > 0.31), reconciled AS (SELECT s.* FROM promotions s INNER JOIN remaining_keys k ON s.channel = k.channel AND s.promo_code = k.promo_code) SELECT DATE_TRUNC('YEAR', ends_on) AS year_start, CASE WHEN discount_pct >= 0.36 THEN 'HIGH' ELSE 'LOW' END AS discount_pct_tier, channel, APPROX_PERCENTILE(discount_pct, ARRAY(0.25, 0.5, 0.75)) AS discount_pct_quartiles, SIZE(COLLECT_SET(promo_code)) AS num_promo_codes, COUNT(*) AS row_count, ROUND(AVG(discount_pct), 2) AS avg_discount_pct, ROUND(AVG(discount_pct), 2) AS avg_discount_pct_2, ROUND(SUM(discount_pct) / NULLIF(COUNT(CASE WHEN channel = 'partner' THEN 1 END), 0), 2) AS discount_pct_per_partner FROM reconciled GROUP BY DATE_TRUNC('YEAR', ends_on), CASE WHEN discount_pct >= 0.36 THEN 'HIGH' ELSE 'LOW' END, channel
